<section class="container narrow section-top"><?php ff_heading('newsletter_preferences','Control your demonstration subscription.'); ?><div class="panel"><p><?=e(t('Subscription preferences are stored locally by this project. No newsletter email delivery is configured.'))?></p><?php if(!empty($token)): ?><div class="notice compact"><p><?=e(t('Keep this private management link to update your subscription later. Anyone with this link can unsubscribe this address.'))?></p></div><p><a class="text-link" href="<?=e(url('newsletter',['token'=>$token]))?>"><?=e(t('subscription_management_link'))?> <?=ff_icon()?></a></p><form class="form-stack" method="post"><?=csrf_field()?><input type="hidden" name="action" value="unsubscribe"><input type="hidden" name="token" value="<?=e($token)?>"><button class="button secondary" type="submit"><?=e(t('unsubscribe'))?></button></form><?php else: ?><form class="form-stack" method="post"><?=csrf_field()?><input type="hidden" name="action" value="subscribe"><label><span><?=e(t('email'))?></span><input name="email" type="email" value="<?=e($user['email']??$_POST['email']??'')?>" required maxlength="190" autocomplete="email"></label><label class="checkbox-label"><input type="checkbox" name="consent" value="1" required><span><?=e(t('I agree to store my email for the demo newsletter.'))?></span></label><button class="button" type="submit"><?=e(t('subscribe'))?></button></form><?php endif ?></div></section>